JS{{
var t = Math.round(@{transpose.value.0});
return (t > 0 ? "+" : "") + t;
}}

JS{
var names = ['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'];
var t = Math.round(@{transpose.value.0});
var n = 60 + t;
var pc = ((n % 12) + 12) % 12;
var oct = Math.floor(n / 12) - 1;
return names[pc] + oct;
}

widgets.onValue:
var semitones = Math.round(Number(value[1]))

// safety clamp
semitones = Math.max(-6, Math.min(6, semitones))

// Wavetable Note PB should be 12.
// This maps -6..+6 semitones into the middle half of a +/-12 pitch bend range.
var bend = Math.round(8192 + (semitones * (8192 / 12)))
bend = Math.max(0, Math.min(16383, bend))

send('/pitch', 2, bend)

widgets.onTouch:
var transpose = Math.round(Number(@{transpose.value.0}))
if (isNaN(transpose)) {
  transpose = 0
}

var note = 60 + transpose
note = Math.max(0, Math.min(127, note))

if (event.type === "start") {
  send('/pitch', 2, 8192)
  send('/note', 2, note, 127)
} else {
  send('/note', 2, note, 0)
  send('/pitch', 2, 8192)
}

